import{_ as e,o as i,c as s,a4 as t}from"./chunks/framework.vNSRaLQv.js";const p=JSON.parse('{"title":"fnOS /vol1 权限被锁 000 事件记录","description":"","frontmatter":{"title":"fnOS `/vol1` 权限被锁 000 事件记录","date":"2026-08-30T00:00:00.000Z"},"headers":[],"relativePath":"posts/fnOS-vol1-权限000问题记录.md","filePath":"posts/fnOS-vol1-权限000问题记录.md"}'),o={name:"posts/fnOS-vol1-权限000问题记录.md"};function l(d,a,n,h,r,c){return i(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="fnos-vol1-权限被锁-000-事件记录" tabindex="-1">fnOS <code>/vol1</code> 权限被锁 000 事件记录 <a class="header-anchor" href="#fnos-vol1-权限被锁-000-事件记录" aria-label="Permalink to &quot;fnOS \`/vol1\` 权限被锁 000 事件记录&quot;">​</a></h1><blockquote><p>文档日期：2026-08-30 涉及设备：部署机 fnos（192.168.31.225，跑 k3s + docker 全家桶）</p></blockquote><hr><h2 id="一、现象" tabindex="-1">一、现象 <a class="header-anchor" href="#一、现象" aria-label="Permalink to &quot;一、现象&quot;">​</a></h2><ul><li><code>/vol1</code> 挂载点及其下 <code>k3s</code>、<code>thumb</code>、<code>vm</code>、<code>1000</code>(admin 用户目录)、<code>lost+found</code> 等顶层目录权限位全部变成 <code>000</code>（<code>d---------</code>），连 root 之外的用户都进不去</li><li>k3s 集群节点 <code>NotReady</code>：kubelet 无法启动，14 个服务全部调度失败（Pending / Terminating）</li><li>首次发现后手动 <code>chmod</code> 修复 + 重启 k3s 可恢复，但<strong>再次重启 fnOS 后 <code>/vol1</code> 根目录又被锁回 000</strong></li></ul><h2 id="二、排查结论" tabindex="-1">二、排查结论 <a class="header-anchor" href="#二、排查结论" aria-label="Permalink to &quot;二、排查结论&quot;">​</a></h2><h3 id="谁引起的-——-fnos-官方已确认的已知内核-bug" tabindex="-1">谁引起的 —— fnOS 官方已确认的已知内核 Bug <a class="header-anchor" href="#谁引起的-——-fnos-官方已确认的已知内核-bug" aria-label="Permalink to &quot;谁引起的 —— fnOS 官方已确认的已知内核 Bug&quot;">​</a></h3><p>官方技术团队定位（飞牛私有云论坛）：</p><blockquote><p>曾经操作（如手动执行 umount / docker build / docker compose 部署），把一些系统文件路径挂载到了其他存储路径， 内核会以为原路径被卸载了，触发特殊权限处理，导致没有权限访问系统文件路径。</p></blockquote><p><strong>触发链</strong>：执行容器类操作（docker build / compose / k3s 调度）→ 触发 umount 冲突 → fnOS 内核误判 → 特殊权限处理把目录权限置 0。</p><p><strong>官方口径</strong>：</p><ul><li>只影响权限，<strong>不影响数据</strong></li><li>重启通常能恢复（偶发，不是每次都复现）</li><li>官方在后续系统更新中会修复（更新内核策略）</li><li>着急可联系飞牛官方私发设备 ID 领内测包</li></ul><h3 id="与本次情况的吻合点" tabindex="-1">与本次情况的吻合点 <a class="header-anchor" href="#与本次情况的吻合点" aria-label="Permalink to &quot;与本次情况的吻合点&quot;">​</a></h3><ul><li>触发时正值 k3s + docker 体系运行（与我们看到的容器调度、FailedCreatePodContainer 事件吻合）</li><li>现象与论坛多个帖子完全一致（docker 部署后文件夹权限全部失效/变 000）</li><li>重启能恢复的官方说法，与我们重启后恢复的事实一致</li></ul><h3 id="排除项" tabindex="-1">排除项 <a class="header-anchor" href="#排除项" aria-label="Permalink to &quot;排除项&quot;">​</a></h3><ul><li>k3s 自身无问题（权限修好后再没复发）</li><li>非用户 &amp; 非普通应用的误操作</li><li>非磁盘/文件系统损坏</li></ul><h2 id="三、修复方案-已部署" tabindex="-1">三、修复方案（已部署） <a class="header-anchor" href="#三、修复方案-已部署" aria-label="Permalink to &quot;三、修复方案（已部署）&quot;">​</a></h2><h3 id="_3-1-手动修复-临时-命令" tabindex="-1">3.1 手动修复（临时，命令） <a class="header-anchor" href="#_3-1-手动修复-临时-命令" aria-label="Permalink to &quot;3.1 手动修复（临时，命令）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">chmod</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 755</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /vol1</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">chmod</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 750</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /vol1/1000</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">chmod</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 755</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /vol1/k3s</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /vol1/thumb</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /vol1/vm</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">chmod</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 700</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /vol1/lost+found</span></span></code></pre></div><h3 id="_3-2-开机自动修复-已部署到-fnos-推荐长期方案" tabindex="-1">3.2 开机自动修复（已部署到 fnos，推荐长期方案） <a class="header-anchor" href="#_3-2-开机自动修复-已部署到-fnos-推荐长期方案" aria-label="Permalink to &quot;3.2 开机自动修复（已部署到 fnos，推荐长期方案）&quot;">​</a></h3><p>脚本 + systemd 服务，开机在本地文件系统挂载后自动执行，幂等：</p><ul><li>脚本：<code>/usr/local/bin/fix-vol1-perms.sh</code></li><li>服务：<code>fix-vol1-perms.service</code>（已 enable）</li><li>日志：<code>/var/log/fix-vol1-perms.log</code></li></ul><p>若 <code>/vol1</code> 又变 000，直接跑一遍脚本即可，无需重启：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">/usr/local/bin/fix-vol1-perms.sh</span></span></code></pre></div><h3 id="_3-3-重启验证结果-2026-08-30-实测通过" tabindex="-1">3.3 重启验证结果（2026-08-30，实测通过） <a class="header-anchor" href="#_3-3-重启验证结果-2026-08-30-实测通过" aria-label="Permalink to &quot;3.3 重启验证结果（2026-08-30，实测通过）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>结果</th></tr></thead><tbody><tr><td>重启后 <code>/vol1</code> 是否被锁</td><td>是（日志：<code>修复 /vol1: 0 -&gt; 755</code>），bug 确认复发</td></tr><tr><td>修复服务是否开机自动执行</td><td>是（<code>Active: exited, status=0/SUCCESS</code>）</td></tr><tr><td>修复是否真实生效</td><td>是（<code>0 -&gt; 755</code>，时序正确，未被&quot;先修后锁&quot;覆盖）</td></tr><tr><td>k3s 节点</td><td><code>Ready</code></td></tr><tr><td>14 个服务</td><td>全部 <code>1/1 Running</code></td></tr></tbody></table><blockquote><p>说明：fnOS 该 bug 为<strong>偶发</strong>，不一定每次重启都复现；若在运行中（如 docker build 后）复发，可手动跑脚本恢复，或后续加 timer 定期自检兜底。</p></blockquote><h2 id="四、参考链接" tabindex="-1">四、参考链接 <a class="header-anchor" href="#四、参考链接" aria-label="Permalink to &quot;四、参考链接&quot;">​</a></h2><ul><li>飞牛论坛贴（官方确认帖）：<code>https://club.fnnas.com/forum.php?mod=viewthread&amp;tid=42361</code>（同问题）</li><li>官方内测包申请/反馈渠道：飞牛论坛私信「飞牛技术同学」</li></ul><h2 id="五、后续建议" tabindex="-1">五、后续建议 <a class="header-anchor" href="#五、后续建议" aria-label="Permalink to &quot;五、后续建议&quot;">​</a></h2><ol><li>关注 fnOS 系统更新，发布修复内核后即可移除临时修复服务（可选）</li><li>操作容器/存储路径挂载时，尽量避免手动物理 umount 系统路径</li><li>定期巡检：<code>stat -c &quot;%a %n&quot; /vol1</code>，非 755 即触发修复脚本</li></ol>`,31)])])}const u=e(o,[["render",l]]);export{p as __pageData,u as default};
